      q2: "फिजी जाने का सबसे अच्छा समय कब है?",
      a2: "मई से अक्टूबर शुष्क, धूप वाला मौसम देता है — समुद्र तट गतिविधियों के लिए आदर्श।",
      q3: "फिजी में कौन-सी मुद्रा चलती है?",
      a3: "फ़िजी डॉलर (FJD) स्थानीय मुद्रा है।",
      q4: "क्या फिजी अकेले यात्रियों के लिए सुरक्षित है?",
      a4: "फिजी आम तौर पर बहुत सुरक्षित है। सामान्य सावधानी बरतें।",
      q5: "हवाई अड्डे से रिसॉर्ट कैसे पहुँचूँ?",
      a5: "अधिकांश रिसॉर्ट ट्रांसफ़र प्रदान करते हैं। नाडी हवाई अड्डे से टैक्सी और बस उपलब्ध हैं।",
      q6: "क्या फिजी में नल का पानी पी सकते हैं?",
      a6: "बोतलबंद पानी की सलाह दी जाती है। रिसॉर्ट सुरक्षित पीने का पानी देते हैं।",
      q7: "फिजी के लिए कौन-से टीके चाहिए?",
      a7: "अधिकांश यात्रियों के लिए कोई अनिवार्य टीका नहीं। अपने डॉक्टर से सलाह लें।",
      q8: "क्या फिजी के लिए यात्रा बीमा चाहिए?",
      a8: "सभी आगंतुकों के लिए यात्रा बीमा दृढ़ता से अनुशंसित है।",
      q9: "फिजी में मौसम कैसा रहता है?",
      a9: "साल भर उष्णकटिबंधीय जलवायु; नवंबर से अप्रैल वर्षा का मौसम।",
      q10: "क्या फिजी में मोबाइल फ़ोन इस्तेमाल कर सकते हैं?",
      a10: "अंतर्राष्ट्रीय रोमिंग काम करती है। हवाई अड्डे पर स्थानीय SIM उपलब्ध हैं।",
      q11: "फिजी में कौन-सी भाषा बोली जाती है?",
      a11: "अंग्रेज़ी, फ़िजी और हिंदी व्यापक रूप से बोली जाती हैं।",
      q12: "क्या फिजी में क्रेडिट कार्ड स्वीकार होते हैं?",
      a12: "प्रमुख क्रेडिट कार्ड रिसॉर्ट और पर्यटन क्षेत्रों में स्वीकार होते हैं।",
      q13: "फिजी में क्या पहनें?",
      a13: "हल्के आरामदायक कपड़े। गाँव की यात्रा के लिए शालीन पोशाक।",
